INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муҳимии дақиқ ҳисоб кардани миқдори бадани зардоб (забардон)</h2>\n<p>Корзиштани зардоб аз сабаби арзиши иқтисодии хеле баланди гулҳои он ва ниёзмандӣ ба давраҳои тӯлонии рушд то расидан ба боссолиҳии истеҳсолот, яке аз серхатар ва ҳассостарин шаклҳои корзишти махсус дар кишоварзии Эрон ҳисоб карда мешавад. Дар ин раванди ҳассоб, идоракунии ҳобҳои ибтидоӣ ва миқдори истинофоти бадан ё ба таври дақиқтар, шумораи гулпояҳо ё колоҳҳои кӯшодашуда дар ҳар воҳиди сатҳ, нақши бунёдии муайян кардани сатҳи баргардониши сармояро дар солҳои аввали корзишт иҷро мекунад. Зардоб аз ҷиҳати табиат тавассути колоҳҳои ҷانبӣ зарба мекунад ва азбаски ин решаҳо аслан «бадан»-и зиндаи растанианд, мафҳуми «миқдори бадан» дар ин ҷо ба шумораи колоҳҳои солим, пухта ва стандартии ҳар гектар нисбат дода мешавад. Бо иҷрои як барномаи дақиқ барои идоракунии зичии корзишт ва истифодаи технологҳои навини беҳтар кардани об, ба монанди системаҳои оварии қатрагӣ ва навъи тиб, деҳқонон метавонанд аз талафоти сарчашмаҳои бераҳмеи об ва пешгирӣ аз паст шудани шадиди самаранокии ҳосил интиқоб нақд ва сифатро кунанд. Дар ин равшнаи умумӣ, мо ниёз дорем, ки тафсилоти техникӣ, илмӣ ва амали беҳтарин кардани ин раванди ҳайати ҳаётиро дар ҳамаи марҳилаҳои он баррасӣ кунем, то боғи зардоб бо оромӣ самаранокии беҳтарини худро дар қадамҳои аввали пайдарпаии худ кунанд.</p>\n\n<h2>Норми стандартии корзишти колоҳҳои зардоб дар гектар</h2>\n<p>Баръикки растаниҳои пурра бо бадан фақат ба гарм шудани бадан дар гектар ниёз доранд, дар корзишти зардоб бояд бар шумораи гулпояҳо ё колоҳҳо таваҷҷуҳ диҳед. Навҳаҳои маъмул аз монанди нарғис, сабези ва ранош, суръати гузаштани гуногунро муайян мекунанд. Дар умум, суръати маъмултарини корзишт байни 80,000 то 120,000 колоҳ дар гектар аст. Агар аз бадани дараҷаи аввал бо вазни тақрибан 5 то 10 грамм истифода баред, ба тақрибан 400 то 600 килограм колоҳи пухтаи омода барои корзишт дар ҳар гектар ниёз доред. Ин рақамҳо вобаста ба шароити замин, хушкӯби замин ва минтакаи кишоварзӣ метавонанд каме тағйир ёбанд. Зарур аст, ки дар назар дошта шавад, ки зичии зиёдатӣ ба рақобати шадиди колоҳҳо дар ҷабби об ва моддаҳои ғизоӣ оварда мерасонад ва дар натиҷа ба паст шудани сифат ва вазни гулпояҳои ҳосили тақлит мёрӯнад. Ин рақобати колоҳҳо дар тағйирёбандаҳои кимиёвӣ ва оварӣ, яке аз муҳимтарин сабабҳои шикаст дар солҳои аввали корзишти зардоб аст, ки бояд хеле диққат карда шавад. Азбаски колоҳҳо ниёзманд ба решаи чуқур ва устувор шудананд, зичии нодуруст метавонад боиси пӯсиши решаҳо ва паст шудани фоизи зиндамонандии растани дар марҳилаҳои ибтидоӣ гардад.</p>\n<h3>Таъсири масофаи калонкуна дар самаранокии корзишт</h3>\n<ul>\n<li><strong>Масофаи байни қаторҳо:</strong> Одатан байни 40 то 50 сантиметр муайян карда мешавад, то ба решаҳо имконияти рушди амудиро медиҳад.</li>\n<li><strong>Масофаи дохили қатор:</strong> Нимеи 10 то 15 сантиметр мувофиқ аст. Масофаи камтар боиси ғирғири колоҳҳо ва пӯсиш мегардад.</li>\n<li><strong>Чуқурии корзишт:</strong> Даргирони колоҳҳо дар чуқурии 3 то 5 сантиметр аз сатҳи замин муҳим аст. Чуқурии зиёдатӣ боиси оҳиста рушд шудани боқимондаи растани мегардад.</li>\n</ul>\n\n<h2>Нақши оварии қатрагӣ ва навъи тиб дар беҳтар кардани корзишт</h2>\n<p>Муҳимтарин мушкил дар идоракунии зичии колоҳҳои зардоб, тақсимоти якхелаи об ва моддаҳои ғизоӣ дар тамоми қабати корзишт аст. Наҳамсамонии оварӣ метавонад боиси шуда кунад, ки колоҳҳо дар қисме аз замин зинда боқӣ монанд, дар ҳолеки дигар минтаҳо ба хоккии нисбӣ ва заиф шудан гирифтор мешаванд. Истифодаи системаҳои <strong>оварии қатрагӣ</strong> ва <strong>навъи тиб</strong> дақиқан ин мушкилро ҳал мекунад. Ин системаҳо обро мустақиман ба ноҳияи реша (Root Zone) мерасонанд ва стресси овариро ба хадди ақал мерасонанд. Бо оварии қатрагӣ, метавон суръати корзиштро то ҳадди иҷозатшуда, бе тарс аз таъҳарри об зиёд кард. Дар минтаҳое, ки об кам аст, истифодаи навъи тиб имконияти идоракунии дақиқтари намии заминро фароҳам мекунад ва аз хушк шудани сатҳии замин, ки ба саломати колоҳҳо таъсири манфии меояд, пешгирӣ мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-زعفران-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر زعفران در هکتار: راهنمای جامع - تصویر 1"/><figcaption>миқдори бадан дар гектар барои корзишти зардоб</figcaption></figure>\n\n<h3>Лайҳанги мувофиқи барои лентаи пускаки заффарон</h3>\n<ol>\n<li><strong>Интихоби лавҳои гилк:</strong> Истифодаи лавҳои 16 ё 20 миллиметрӣ, ки бевосита дар сатҳи сатҳҳои кӯршотӣ ҷойгир мешаванд.</li>\n<li><strong>Қатъ ва пайваст кардан:</strong> Лавҳо бояд бо фосилаҳои мунтазам қатъ шуда, ба лави асосӣ пайваст карда шаванд, то фишори мувофиқ дар тамоми дарозии лав ҳифз гардад.</li>\n<li><strong>Санҷиши фишор:</strong> Пеш аз кӯршотан, ҳатман системаи обирониро санҷед, то таъмини нол будани он ва истеҳсоми фишори кофии помпа таъмин гардад.</li>\n</ol>\n<p>Барои маълумоти бештар дар бораи такмонии дурусти ин системаҳо, мақолаи роҳнамои <a href="https://navar-abyari.ir/%d9%85%d8%b1%d8%a7%d8%ad%d9%84-%d9%86%d8%b5%d8%a8-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be/">Марҳилаҳои насби лентаи пускакӣ</a> ро хонед. Инчунин, обиронии марҳилавӣ дар асоси кампостӣ метавонад ба идоракунии беҳтари манбаъҳо кӯмак расонад.</p>\n\n<h2>Маслиҳотҳои амалӣ барои кӯршоти муваффақ</h2>\n<h3>Омодагии сохтор ва хок</h3>\n<p>Пеш аз кӯршотани колмокҳо, хок бояд чуқур корд карда шавад, то таъмини нӯфиши мувофиқ барои нафаскашии руйшҳо таъмин гардад. Заффарон ба хокҳои сабу зехкшуда мехушад. pH-и мувофиқи хок бояд байни 6 то 7.5 бошад. Дар минтақаҳое, ки хокҳои ширҳо доранд, корд кардани кирчол пеш аз кӯршотан тавсия мешавад. Инчунин, истифодаи кӯдҳои органикӣ, ба монанди компост ва кӯдҳои ахрӣ, барои бойнависии хок ва ҷабди беҳтари моддаҳои ғизоӣ барои колмокҳои ҷавон зарур аст. Омодагии дурусти сохтор тавассути корди чуқур, рӯйшди беҳтар ва тезтари колмокҳоро осон мекунад ва асоси мустаҳкам барои рушди оҳангор дар фаслҳои оянда мегузорад.</p>\n<h3>Идоракунии зарароварон ва бемориҳо</h3>\n<p>Зичии баланди колмокҳо муҳити хатарнок барои вобароии занбӯруғӣ ва ҳашароти руйшҳо эҷод мекунад. Истифодаи занбӯруғкӯшҳои пешгирикунанда ва санҷиши мунтазами системаи обиронӣ барои пешгирии ҷамъ шудани намдории иловагӣ аз чораҳои асосӣ мебошад. Системаи лентаи пускакӣ бо кам кардани намдории сатҳӣ, муқовимати беҳтар ба вобароии занбӯруғӣ эҷод мекунад. Назорати дақиқи намдории хок тавассути таҷҳизоти муосири обиронӣ, яке аз роҳҳои арзонтарин ва самараноктарин барои мубориза бо патогенҳои хокӣ аст, ки дар шартҳои намдории баланди сатҳӣ фаъол мешаванд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-زعفران-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر زعفران در هکتار: راهنمای جامع - تصویر 2"/><figcaption>Norma of seeding per hectare of crop of Zafarun</figcaption></figure>\n\n<h3>Ҳисобкиши молиявӣ ва буҷарезӣ</h3>\n<p>Қабули колмокҳои дараҷаи якум тағирёбии зиёд дорад. Кишоварон бояд дар асоси нархи рӯзона ва сифати харидашуда, ҳамагӣ ҳаролатҳои истеҳсолотро ҳисоб кунанд. Нархатии системаи обиронии пускакӣ ё лентавӣ, бо сабаби бартарии истифодаи об ва зиёд шудани ҳосил, одатан дар давраи кӯтиҳтар аз як мавсими кӯршотӣ ҳисоб карда мешавад. Барои муқоиса бо маҳсулоти кишоварзӣ дигар, шумо метавонед ба роҳнамои <a href="https://navar-abyari.ir/shallot-seed-quantity-per-hectare-guide/">Микдори боби шалот дар якто</a> ва <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%a8%d8%a7%d9%85%db%8c%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми даромади бамия дар якто</a> таҳқиқ кунед, то аз гуногунии иқтисодии кӯтӯбҳои гуногун огоҳ шавед.</p>\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<h3>Оё ман метавонам барои кам кардани маблағ сарфароз аз кӯлҳои дараҷаи дуюм истифода барам?</h3>\n<p>Истифодаи кӯлҳои дараҷаи дуюм ё ноком рӯбарӯи хавфи бисёр баланд аст. Ин кӯлҳо одатан ноком мебошанд, тӯли ҳаёти растаро коҳиш медиҳанд ва даромади солҳои авваланро ба таври шадид таъсир мерасонанд. Тавсия карда мешавад, ки танҳо аз кӯлҳои дорои вазн ва андозаи стандарти истифода баред. Кӯлҳои бинӯм, ки решаҳои онҳо зиён ёфтаанд, пас аз кӯтуб бо суръати паст нам ва моддаҳои ғизоиро ҷаббиш мекунанд ва дар рақобат бо кӯлҳои солим дар шикоф ҳамеша ноком шуда меистанд. Бинобар ин, ҳарчи маблағи аввалии баланд барои хариди кӯлҳои стандартӣ, дар ниҳолат даромади баландтар ва саломатии маҷмуи растаро ба вуҷуд меорад.</p>\n<h3>Оё обёрӣи чуқур барои зафарон зарур аст?</h3>\n<p>Гарчанде ки обёрӣи бозгӯи маъмул аст, вале обёрӣи чуқур ё тасмаи тикӣ бо сабаби таъсиррасонии пурраи 30 то 50 фоизӣ дар истеъмоли об ва тақсимоти дақиқтари моддаҳои ғизоӣ, боз ҳам тавсия карда мешавад, махсусан дар минтақаҳои хушк ва обноқ. Барои нигоҳубини дурусти ин пурравонҳо, мақолаи <a href="https://navar-abyari.ir/%d9%86%da%af%d9%87%d8%af%d8%a7%d8%b1%db%8c-%d9%88-%d9%85%d8%af%db%8c%d8%b1%db%8c%d8%aa-%d9%86%d9%88%d8%a7%d8%b1-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%aa%db%8c%d9%be/">Нигоҳубин ва идоракунии тасмаи обёрӣи тикӣ</a> ро хонед. Дармонидани фишори якхела дар тасмаҳо, сри асосии кори муваффақии ин система дар минтақаҳои васеи кӯтуби зафарон аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-زعفران-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر زعفران در هکتار: راهنمای جامع - تصویر 3"/><figcaption>seed rate per hectare crop зaфарон</figcaption></figure>\n\n<h3>Беҳтарин вақти кӯтуби зафарон кист аст?</h3>\n<p>Беҳтарин вақти кӯтуби кӯлҳо охири тобистон (субҳ ва абан) аст, вақте ки кӯлҳо ороҳӣ мегиранд ва барои афзоиши нав аз нав тайёранд. Кӯтуби дер мондан метавонад боиси коҳиши дарсади афзоиш дар баҳор гардад. Дар ин фосила, ҳарорати хок ба дараҷаи лозима мувофиқ аст, ки решагирӣи барвақт ва қобилиятмандтарро имконпазир кунад. Кӯтубҳои хеле барвақт метавонанд бо нопарошиҳои тобистона мувофиқат кунанд ва кӯтуби дер мондан, имкониятҳои созандаро кам мекунад.</p>\n\n<h2>Хулоса ва тавсияи ниҳоӣ</h2>\n<p>Микдори боби зафарон (кӯл) дар якто як муносибати тағйирёбанда аст, ки бевосита ба намуди хок, иқлим ва системаи обёрӣи шумо вобаста аст. Бо интихоби чизи дуруст (тақрибан 100,000 кӯл дар якто) ва ба коргирӣ кардани системаҳои пешрафтаи обёрӣи мисли тасмаи тикӣ, шумо метавонед сарватнокии иқтисодии кӯтуби худро ба андозаи баландтар расонед. Ин усул на танҳо хароҷотҳои амалиётӣро кам мекунад, балки бо идоракунии дақиқи манбаъҳо, муҳити зистро низ муҳофизат мекунад. Барои маълумоти бештар дар бораи <a href="https://navar-abyari.ir/broccoli-harvest-per-hectare-guide/">Ҳаҷми даромади гули гирдлери бросукли дар якто</a> ва микдори боби ҷонг и дана дар якто, ба манбаъҳои муассиб ошкор кунед. Муваффақият дар кӯтуби зафарон тобоварӣ, дақиқӣ ва истифода аз технологияи имрӯзаи кишовариро талаб мекунад.</p>','Миқдори бубӯри зعفرон дар ҳектар: Равнамои пурра','Оё шум медонед, ки миқдори бӯди зафаронро ба ҳар як гектар чӣ тавр бояд ҳисоб кард? Дар ин раҳнамоии мукаммал, мо хосили беҳтарини пашти колби зафаронро ва таъсири онро ба ҳосилӣ баррасӣ мекунем. Бо усулҳои навтави обёрии қатқатӣ ва навори тип, шумо метавонед аз хароми об ва паст шудани сифат пешгирӣ кунед. Ин мақола як нақшаи роҳи пурра барои деҳқонҳо ва кишинандагони зафарон аст, ки дар ҷустуҷӯи афзуншавии истеҳсолот ва кам кардани хароҷот қарор доранд. Бо мо ҳамроҳ шавед то беҳтарин усулҳоро кашф кунед.','publish','closed','closed','miqdori-bubori-zaferon-dar-hektar',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
