INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Бо ин дастур чӣ тавр аз корбурии баҳо бо усули обёркунии қатрагӣ (drip irrigation) истифода баред. Дар ин мукамот асосҳои техникӣ, тақвими корҳо ва нуктаҳои амалӣ барои зиёд кардани ҳосилот оварда шудааст. Муқовимат ба беморӣ ва истифодаи мувофиқи оби сипаракӣ мебошад.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
